        rom[484] = {7'h54, 19'h4bdc6, 30'h36b8d988, 41'h1d9aefcfc96, 52'haad860c0b3d1b, 60'hecf482d8e680094};
        rom[485] = {7'h54, 19'h4bf6b, 30'h36cbd3eb, 41'h1da5343ff1e, 52'hab13a0e42bb9e, 60'hed9f78d802dd1e7};
        rom[486] = {7'h54, 19'h4c111, 30'h36ded4e2, 41'h1daf7c3faac, 52'hab4ef594134eb, 60'hee4aaa21885204d};
        rom[487] = {7'h55, 19'h4c2b7, 30'h36f1dc71, 41'h1db9c7d0303, 52'hab8a5ed78aed2, 60'heef616ca06de62c};
        rom[488] = {7'h55, 19'h4c45d, 30'h3704ea99, 41'h1dc416f2beb, 52'habc5dcb5b56ac, 60'hefa1bee615a377d};
