        rom[490] = {7'h55, 19'h4c7ac, 30'h372b1ac0, 41'h1dd8bff2eba, 52'hac3d165ebabab, 60'hf0f9c1cb64139b9};
        rom[491] = {7'h55, 19'h4c955, 30'h373e3cc2, 41'h1de319d3053, 52'hac78d237e79b7, 60'hf1a61cbdf5bf6df};
        rom[492] = {7'h55, 19'h4cafe, 30'h37516567, 41'h1ded774a1e8, 52'hacb4a2c86b79f, 60'hf252b376bbaa755};
        rom[493] = {7'h55, 19'h4cca7, 30'h376494b1, 41'h1df7d859763, 52'hacf0881775946, 60'hf2ff860a70c3196};
        rom[494] = {7'h55, 19'h4ce51, 30'h3777caa3, 41'h1e023d024b7, 52'had2c822c37a67, 60'hf3ac948dd7283ed};
        rom[495] = {7'h55, 19'h4cffc, 30'h378b073e, 41'h1e0ca545ddd, 52'had68910de5ead, 60'hf459df15b82bc54};
        rom[496] = {7'h56, 19'h4d1a7, 30'h379e4a85, 41'h1e1711256d5, 52'hada4b4c3b71bc, 60'hf50765b6e45506d};
        rom[497] = {7'h56, 19'h4d353, 30'h37b1947a, 41'h1e2180a23a6, 52'hade0ed54e473c, 60'hf5b52886336357f};
        rom[498] = {7'h56, 19'h4d500, 30'h37c4e51f, 41'h1e2bf3bd85f, 52'hae1d3ac8a9aef, 60'hf66327988450885};
        rom[499] = {7'h56, 19'h4d6ad, 30'h37d83c78, 41'h1e366a78915, 52'hae599d26450b8, 60'hf7116302bd53648};
        rom[500] = {7'h56, 19'h4d85a, 30'h37eb9a85, 41'h1e40e4d49e3, 52'hae961474f74a9, 60'hf7bfdad9cbe238f};
        rom[501] = {7'h56, 19'h4da08, 30'h37feff4b, 41'h1e4b62d2eed, 52'haed2a0bc03b17, 60'hf86e8f32a4b5551};
        rom[502] = {7'h56, 19'h4dbb7, 30'h38126aca, 41'h1e55e474c5c, 52'haf0f4202b00a0, 60'hf91d802243c98fd};
        rom[503] = {7'h56, 19'h4dd66, 30'h3825dd05, 41'h1e6069bb662, 52'haf4bf85044a41, 60'hf9ccadbdac62cd1};
        rom[504] = {7'h57, 19'h4df16, 30'h383955fe, 41'h1e6af2a8136, 52'haf88c3ac0c55c, 60'hfa7c1819e90e835};
        rom[505] = {7'h57, 19'h4e0c7, 30'h384cd5b9, 41'h1e757f3c118, 52'hafc5a41d547cd, 60'hfb2bbf4c0ba6432};
        rom[506] = {7'h57, 19'h4e278, 30'h38605c36, 41'h1e800f78a4d, 52'hb00299ab6cff3, 60'hfbdba3692d523ed};
        rom[507] = {7'h57, 19'h4e42a, 30'h3873e979, 41'h1e8aa35f123, 52'hb03fa45da84c1, 60'hfc8bc4866e8bd32};
        rom[508] = {7'h57, 19'h4e5dc, 30'h38877d84, 41'h1e953af09ed, 52'hb07cc43b5b5cc, 60'hfd3c22b8f72010f};
        rom[509] = {7'h57, 19'h4e78f, 30'h389b185a, 41'h1e9fd62e907, 52'hb0b9f94bddb55, 60'hfdecbe15f63247f};
        rom[510] = {7'h57, 19'h4e942, 30'h38aeb9fb, 41'h1eaa751a2d3, 52'hb0f743968965e, 60'hfe9d96b2a23e91b};
        rom[511] = {7'h57, 19'h4eaf6, 30'h38c2626c, 41'h1eb517b4bba, 52'hb134a322bb0b2, 60'hff4eaca4391c5e0};
    end
    reg [WROM-1:0] rom_q;
    reg [RW-1:0]   w_r;
    reg            v_r;
    always @(posedge clk) begin
        if (rst) v_r <= 1'b0;
        else     v_r <= in_valid;
        rom_q <= rom[f[RW+K-1 -: K]];
        w_r   <= f[RW-1:0];
    end
    wire [W0-1:0] c0 = {1'b1, rom_q[W0-2:0]};
    wire [W1-1:0] c1 = rom_q[60 +: W1];
    wire [W2-1:0] c2 = rom_q[112 +: W2];
    wire [W3-1:0] c3 = rom_q[153 +: W3];
    wire [W4-1:0] c4 = rom_q[183 +: W4];
    wire [W5-1:0] c5 = rom_q[202 +: W5];

    // c0 + c1*w, the wide product, held if the chain takes longer.
    wire v_p;
    wire [W1+T1-1:0] p1;
    _zkf_pmul #(
        .WA(W1), .WB(T1), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT)
    ) u_p1 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c1), .b(w_r[RW-1 -: T1]),
        .out_valid(v_p), .sb_out(), .p(p1)
    );
    wire [W0-1:0] c0_d;
    zkf_pipe #(.W(W0), .N(NK)) u_c0 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c0), .out_valid(), .out(c0_d)
    );
    wire [W1-1:0] p1_d;
    zkf_pipe #(.W(W1), .N(NK - 1 - STAGE_PRODUCT)) u_p1_d (
        .clk(clk), .rst(rst), .in_valid(v_p), .in(p1[W1+T1-1:T1]), .out_valid(out_valid), .out(p1_d)
    );

    wire [TS-1:0] ws = w_r[RW-1 -: TS];
    wire v_s;  // the valid of the square
    // The pairs c[2i] + c[2i+1]*w above the wide one, each held for its turn.
    wire [W3+T3-1:0] p3;
    _zkf_pmul #(
        .WA(W3), .WB(T3), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_ODD), .STAGE_OUTPUT(0)
    ) u_p3 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c3), .b(w_r[RW-1 -: T3]),
        .out_valid(), .sb_out(), .p(p3)
    );
    wire [W2-1:0] c2_d;
    zkf_pipe #(.W(W2), .N(STAGE_PRODUCT_ODD)) u_c2 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c2), .out_valid(), .out(c2_d)
    );
    wire [W2-1:0] pair1_0 = c2_d + p3[W3+T3-1:T3];
    wire [W2-1:0] pair1;
    zkf_pipe #(.W(W2), .N(NF + 1 * (1 + STAGE_PRODUCT_CHAIN) - STAGE_PRODUCT_ODD)) u_pair1 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(pair1_0), .out_valid(), .out(pair1)
    );
    localparam integer NP5 = (STAGE_PRODUCT_ODD > 1) ? 1 : STAGE_PRODUCT_ODD;  // what a product this narrow admits
    wire [W5+T5-1:0] p5;
    _zkf_pmul #(
        .WA(W5), .WB(T5), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(NP5), .STAGE_OUTPUT(0)
    ) u_p5 (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(c5), .b(w_r[RW-1 -: T5]),
        .out_valid(), .sb_out(), .p(p5)
    );
    wire [W4-1:0] c4_d;
    zkf_pipe #(.W(W4), .N(NP5)) u_c4 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(c4), .out_valid(), .out(c4_d)
    );
    wire [W4-1:0] pair2_0 = c4_d + p5[W5+T5-1:T5];
    wire [W4-1:0] pair2;
    zkf_pipe #(.W(W4), .N(NF - NP5)) u_pair2 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(pair2_0), .out_valid(), .out(pair2)
    );
    // chain = w**2 * (pair1 + w**2 * pair2), each product registered as the bits the next sum takes.
    wire [TS+TS-1:0] sq;
    _zkf_pmul #(
        .WA(TS), .WB(TS), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(SQP), .STAGE_OUTPUT(SQO)
    ) u_sq (
        .clk(clk), .rst(rst), .in_valid(v_r), .sb_in(1'b0), .a(ws), .b(ws),
        .out_valid(v_s), .sb_out(), .p(sq)
    );
    wire [Q0-1:0] sq_0;
    wire v_0;
    zkf_pipe #(.W(Q0), .N(NF - STAGE_PRODUCT_SQUARE)) u_sq_0 (
        .clk(clk), .rst(rst), .in_valid(v_s), .in(sq[2*TS-1 -: Q0]), .out_valid(v_0), .out(sq_0)
    );
    wire v_p4, v_1;
    wire [W4+Q1-1:0] p4;
    _zkf_pmul #(
        .WA(W4), .WB(Q1), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_CHAIN), .STAGE_OUTPUT(0)
    ) u_p4 (
        .clk(clk), .rst(rst), .in_valid(v_0), .sb_in(1'b0), .a(pair2), .b(sq_0[Q0-1 -: Q1]),
        .out_valid(v_p4), .sb_out(), .p(p4)
    );
    wire [W4-1:0] p4_r;
    zkf_pipe #(.W(W4), .N(1)) u_p4_r (
        .clk(clk), .rst(rst), .in_valid(v_p4), .in(p4[W4+Q1-1:Q1]), .out_valid(v_1), .out(p4_r)
    );
    wire [W2-1:0] chain1 = pair1 + p4_r;
    wire [Q0-1:0] sq_1;
    zkf_pipe #(.W(Q0), .N(1 + STAGE_PRODUCT_CHAIN)) u_sq_1 (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(sq_0), .out_valid(), .out(sq_1)
    );
    wire [W2+Q0-1:0] p2;
    _zkf_pmul #(
        .WA(W2), .WB(Q0), .SIGNED(0), .WSB(1),
        .WMULTIPLIER(WMULTIPLIER), .STAGE_PRODUCT(STAGE_PRODUCT_CHAIN), .STAGE_OUTPUT(0)
    ) u_p2 (
        .clk(clk), .rst(rst), .in_valid(v_1), .sb_in(1'b0), .a(chain1), .b(sq_1),
        .out_valid(), .sb_out(), .p(p2)
    );
    wire [W2-1:0] p2_d;
    zkf_pipe #(.W(W2), .N(NK - NL)) u_p2_d (
        .clk(clk), .rst(1'b0), .in_valid(1'b0), .in(p2[W2+Q0-1:Q0]), .out_valid(), .out(p2_d)
    );
    reg  [W2-1:0] chain;
    always @(posedge clk) chain <= p2_d;
    assign s = c0_d + p1_d + chain;
endmodule

